func TestEVEnergyOfferTypeUnmarshalJSON(t *testing.T) {
	tests := []struct {
		name    string
		input   []byte
		wantErr error
	}{
		{
			name:  "accepts valid input",
			input: []byte(`{"evPowerSchedule":{"timeAnchor":"2024-01-01T00:00:00Z","evPowerScheduleEntries":[{"duration":1,"power":1.0}]},"evAbsolutePriceSchedule":{"timeAnchor":"2024-01-01T00:00:00Z","currency":"sam","priceAlgorithm":"sample","evAbsolutePriceScheduleEntries":[{"duration":1,"evPriceRule":[{"energyFee":1.0,"powerRangeStart":1.0}]}]}}`),
		},
		{
			name:    "rejects missing evPowerSchedule",
			input:   []byte(`{"evAbsolutePriceSchedule":{"timeAnchor":"2024-01-01T00:00:00Z","currency":"sam","priceAlgorithm":"sample","evAbsolutePriceScheduleEntries":[{"duration":1,"evPriceRule":[{"energyFee":1.0,"powerRangeStart":1.0}]}]}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var s EVEnergyOfferType
			err := json.Unmarshal(tt.input, &s)

			if !errors.Is(err, tt.wantErr) {
				t.Errorf("unexpected error\ngot:  %v\nwant: errors.Is match for %v", err, tt.wantErr)
			}
		})
	}

	t.Run("rejects wrong JSON type", func(t *testing.T) {
		var s EVEnergyOfferType
		data := []byte(`1`)

		err := json.Unmarshal(data, &s)

		var typeErr *json.UnmarshalTypeError
		if !errors.As(err, &typeErr) {
			t.Errorf("unexpected error\ngot:  %v\nwant: errors.As match for %v", err, typeErr)
		}
	})
}

func TestEventDataTypeUnmarshalJSON(t *testing.T) {
	tests := []struct {
		name    string
		input   []byte
		wantErr error
	}{
		{
			name:  "accepts valid input",
			input: []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
		},
		{
			name:    "rejects missing timestamp",
			input:   []byte(`{"eventId":0,"trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
		{
			name:    "rejects missing trigger",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
		{
			name:    "rejects missing actualValue",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
		{
			name:    "rejects missing eventNotificationType",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
		{
			name:    "rejects missing component",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
		{
			name:    "rejects missing variable",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}}}`),
			wantErr: ocpp.ErrOccurenceConstraintViolation,
		},
		{
			name:    "rejects eventId out of range",
			input:   []byte(`{"eventId":-1,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects cause out of range",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":-1,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects actualValue exceeding max length",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects techCode exceeding max length",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects techInfo exceeding max length",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects transactionId exceeding max length",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects transactionId outside identifierString charset",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"####################################","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects variableMonitoringId out of range",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":-1,"eventNotificationType":"HardWiredNotification","severity":0,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
		{
			name:    "rejects severity out of range",
			input:   []byte(`{"eventId":0,"timestamp":"2024-01-01T00:00:00Z","trigger":"Alerting","cause":0,"actualValue":"sample","techCode":"sample","techInfo":"sample","cleared":true,"transactionId":"A1","variableMonitoringId":0,"eventNotificationType":"HardWiredNotification","severity":-1,"component":{"name":"A1","instance":"A1","evse":{"id":0,"connectorId":0}},"variable":{"name":"A1","instance":"A1"}}`),
			wantErr: ocpp.ErrPropertyConstraintViolation,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var s EventDataType
			err := json.Unmarshal(tt.input, &s)

			if !errors.Is(err, tt.wantErr) {
				t.Errorf("unexpected error\ngot:  %v\nwant: errors.Is match for %v", err, tt.wantErr)
			}
		})
	}

	t.Run("rejects wrong JSON type", func(t *testing.T) {
		var s EventDataType
		data := []byte(`1`)

		err := json.Unmarshal(data, &s)

		var typeErr *json.UnmarshalTypeError
		if !errors.As(err, &typeErr) {
			t.Errorf("unexpected error\ngot:  %v\nwant: errors.As match for %v", err, typeErr)
		}
	})
}

